static const char *arg(int c,char**v,const char*n){for(int i=2;i+1<c;i++)if(!strcmp(v[i],n))return v[i+1];return NULL;}
static char *slurp(const char*p,size_t*n){FILE*f=fopen(p,"rb");char*b=NULL;long z;if(!f)return NULL;if(fseek(f,0,SEEK_END)||((z=ftell(f))<0)||fseek(f,0,SEEK_SET)){fclose(f);return NULL;}b=malloc((size_t)z+1);if(!b){fclose(f);return NULL;}if(z&&fread(b,1,(size_t)z,f)!=(size_t)z){free(b);fclose(f);return NULL;}b[z]=0;fclose(f);if(n)*n=(size_t)z;return b;}
static int sql(sqlite3*d,const char*q){char*e=NULL;int rc=sqlite3_exec(d,q,NULL,NULL,&e);if(rc!=SQLITE_OK){fprintf(stderr,"sqlite: %s\n",e?e:"error");sqlite3_free(e);return 0;}return 1;}
static int mkdir_ok(const char*p){return p&&*p&&(mkdir(p,0750)==0||errno==EEXIST);}
static uint64_t hash64(const char*s){uint64_t h=1469598103934665603ULL;for(const unsigned char*p=(const unsigned char*)s;*p;p++){h^=*p;h*=1099511628211ULL;}return h;}
static int emit(const char*dir,const char*key,const char*body){char sub[1200],path[1400],tmp[1440];FILE*f=NULL;if(!mkdir_ok(dir)||snprintf(sub,sizeof(sub),"%s/MaterialCompiler-external",dir)>=(int)sizeof(sub)||!mkdir_ok(sub)||snprintf(path,sizeof(path),"%s/%016llx.json",sub,(unsigned long long)hash64(key))>=(int)sizeof(path))return 0;if(!access(path,F_OK))return 1;if(snprintf(tmp,sizeof(tmp),"%s.tmp",path)>=(int)sizeof(tmp)||(f=fopen(tmp,"w"))==NULL)return 0;if(fputs(body,f)<0||(!strchr(body,'\n')&&fputc('\n',f)==EOF)||fflush(f)||fsync(fileno(f))||fclose(f)||rename(tmp,path)){if(f)fclose(f);unlink(tmp);return 0;}return 1;}
/* A schedule frontier can request a fresh observation only for an already
 * admitted physical lease. The regenerated envelope is still merely a
 * MaterialCompiler request; WebSub/ForeignTwin independently own any read. */
static int emit_refresh(const char*out,const char*refresh,const char*acquire,const char*identity,const char*owner){char key[1800],body[4096];if(!out||!refresh||!*refresh||!acquire||!identity||!owner||snprintf(key,sizeof(key),"%s:%s",refresh,acquire)>=(int)sizeof(key)||snprintf(body,sizeof(body),"{\"schema\":\"bonfyre-lowering-handoff.v1\",\"delta_id\":\"resource-weather-refresh:%s:%s\",\"identity\":\"%s\",\"candidate_kind\":\"external_occurrence\",\"owner_ref\":\"%s\",\"lowerer_ref\":\"MaterialCompiler:external\",\"refresh_reason\":\"source_schedule_due\",\"truth\":\"dependency_cut_only\"}",refresh,acquire,identity,owner)>=(int)sizeof(body))return 0;return emit(out,key,body);}
static int lease_count(sqlite3*d,const char*id){sqlite3_stmt*q=NULL;int n=-1;if(sqlite3_prepare_v2(d,"SELECT count(*) FROM material_lease WHERE identity=?1",-1,&q,NULL)==SQLITE_OK){sqlite3_bind_text(q,1,id,-1,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW)n=sqlite3_column_int(q,0);}sqlite3_finalize(q);return n;}
static int field(sqlite3*d,const char*b,size_t n,const char*path,char*out,size_t cap){sqlite3_stmt*q=NULL;char expr[256];int ok=0;if(snprintf(expr,sizeof(expr),"SELECT json_extract(?1,'$.%s')",path)>=(int)sizeof(expr)||sqlite3_prepare_v2(d,expr,-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,b,(int)n,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_text(q,0)){snprintf(out,cap,"%s",(const char*)sqlite3_column_text(q,0));ok=*out!='\0';}sqlite3_finalize(q);return ok;}
static int has_column(sqlite3*d,const char*table,const char*column){sqlite3_stmt*q=NULL;int found=0;char query[256];if(snprintf(query,sizeof(query),"PRAGMA table_info(%s)",table)>=(int)sizeof(query)||sqlite3_prepare_v2(d,query,-1,&q,NULL)!=SQLITE_OK)return 0;while(sqlite3_step(q)==SQLITE_ROW){const char*n=(const char*)sqlite3_column_text(q,1);if(n&&!strcmp(n,column)){found=1;break;}}sqlite3_finalize(q);return found;}
static int ingest_acquire_file(sqlite3*d,const char*path){size_t n=0;char*b=slurp(path,&n),schema[96]={0},delta[256]={0},id[512]={0},owner[640]={0},lower[96]={0};sqlite3_stmt*q=NULL;int ok=0;if(!b)goto out;if(!field(d,b,n,"schema",schema,sizeof(schema))||strcmp(schema,"bonfyre-lowering-handoff.v1")||!field(d,b,n,"delta_id",delta,sizeof(delta))||strncmp(delta,"material-lease:",15)||!field(d,b,n,"identity",id,sizeof(id))||!field(d,b,n,"owner_ref",owner,sizeof(owner))||!field(d,b,n,"lowerer_ref",lower,sizeof(lower))||strcmp(lower,"MaterialCompiler:external"))goto out;if(sqlite3_prepare_v2(d,"INSERT INTO weather_pending(acquire_id,identity,owner_ref,handoff_json,state,tier,updated_at) VALUES(?1,?2,?3,?4,'pending','UNKNOWN',?5) ON CONFLICT(acquire_id) DO NOTHING",-1,&q,NULL)!=SQLITE_OK)goto out;sqlite3_bind_text(q,1,delta,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,id,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,3,owner,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,4,b,(int)n,SQLITE_TRANSIENT);sqlite3_bind_int64(q,5,(sqlite3_int64)time(NULL));ok=sqlite3_step(q)==SQLITE_DONE;out:sqlite3_finalize(q);free(b);return ok;}
static int ingest_cancel_file(sqlite3*d,sqlite3*leases,const char*path,int*cancelled){size_t n=0;char*b=slurp(path,&n),schema[96]={0},id[512]={0};sqlite3_stmt*q=NULL;int ok=0;if(!b)goto out;if(!field(d,b,n,"schema",schema,sizeof(schema))||strcmp(schema,"bonfyre-material-observation-cancel.v1")||!field(d,b,n,"identity",id,sizeof(id)))goto out;int refs=lease_count(leases,id);if(refs<0)goto out;if(refs==0){if(sqlite3_prepare_v2(d,"UPDATE weather_pending SET state='cancelled',updated_at=?2 WHERE identity=?1 AND state='pending'",-1,&q,NULL)!=SQLITE_OK)goto out;sqlite3_bind_text(q,1,id,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(q,2,(sqlite3_int64)time(NULL));if(sqlite3_step(q)!=SQLITE_DONE)goto out;*cancelled+=sqlite3_changes(d);}ok=1;out:sqlite3_finalize(q);free(b);return ok;}
static int scan(sqlite3*d,sqlite3*l,const char*root,int cancel,int*files,int*cancelled){char dir[1200],path[1400];DIR*h;struct dirent*e;if(!root||snprintf(dir,sizeof(dir),"%s/MaterialCompiler-external",root)>=(int)sizeof(dir))return 1;h=opendir(dir);if(!h)return errno==ENOENT;while((e=readdir(h))){size_t z=strlen(e->d_name);if(z<6||strcmp(e->d_name+z-5,".json"))continue;if(snprintf(path,sizeof(path),"%s/%s",dir,e->d_name)>=(int)sizeof(path)){closedir(h);return 0;}if(!(cancel?ingest_cancel_file(d,l,path,cancelled):ingest_acquire_file(d,path))){closedir(h);return 0;}(*files)++;}closedir(h);return 1;}
static int weather_value(sqlite3*d,const char*weather,const char*source,const char*path,char*out,size_t cap,const char*fallback){size_t n=0;char*b=slurp(weather,&n);sqlite3_stmt*q=NULL;int ok=0;snprintf(out,cap,"%s",fallback);if(!b)return 1;if(sqlite3_prepare_v2(d,"SELECT json_extract(value,?3) FROM json_each(?1,'$.sources') WHERE json_extract(value,'$.source')=?2 LIMIT 1",-1,&q,NULL)!=SQLITE_OK)goto done;sqlite3_bind_text(q,1,b,(int)n,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,source,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,3,path,-1,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_text(q,0))snprintf(out,cap,"%s",(const char*)sqlite3_column_text(q,0));ok=1;done:sqlite3_finalize(q);free(b);return ok;}
static int weather_tier(sqlite3*d,const char*weather,const char*source,char*out,size_t cap){return weather_value(d,weather,source,"$.tier",out,cap,"UNKNOWN");}
static int weather_decision(sqlite3*d,const char*weather,const char*source,char*out,size_t cap){return weather_value(d,weather,source,"$.decision",out,cap,"");}
static int source_ref(sqlite3*a,const char*id,char*out,size_t cap){sqlite3_stmt*q=NULL;int ok=0;if(sqlite3_prepare_v2(a,"SELECT source_ref FROM occurrence WHERE id=?1",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,id,-1,SQLITE_TRANSIENT);if(sqlite3_step(q)==SQLITE_ROW&&sqlite3_column_text(q,0)){snprintf(out,cap,"%s",(const char*)sqlite3_column_text(q,0));ok=*out!='\0';}sqlite3_finalize(q);return ok;}
static int remember_source(sqlite3*d,const char*acquire_id,const char*source){sqlite3_stmt*q=NULL;int ok=0;if(sqlite3_prepare_v2(d,"UPDATE weather_pending SET source_ref=?2 WHERE acquire_id=?1 AND (source_ref IS NULL OR source_ref<>?2)",-1,&q,NULL)!=SQLITE_OK)return 0;sqlite3_bind_text(q,1,acquire_id,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,source,-1,SQLITE_TRANSIENT);ok=sqlite3_step(q)==SQLITE_DONE;sqlite3_finalize(q);return ok;}
/* --source is a persisted-index forwarding filter: it changes no nonmatching
 * intent and the query visits only the named source's pending leases. */
static int drain(sqlite3*d,sqlite3*a,sqlite3*l,const char*weather,const char*out,const char*only_source,const char*refresh_id,int limit,int*admitted,int*refreshed,int*held,int*stale,int*examined){sqlite3_stmt*q=NULL,*mark=NULL;int scoped=only_source&&*only_source,refresh=refresh_id&&*refresh_id;
 if(sqlite3_prepare_v2(d,scoped?"SELECT acquire_id,identity,owner_ref,handoff_json,state,COALESCE(refresh_delta_id,'') FROM weather_pending WHERE source_ref=?1 AND (state='pending' OR (state='admitted' AND ?2<>'')) ORDER BY rowid LIMIT ?3":"SELECT acquire_id,identity,owner_ref,handoff_json,state,COALESCE(refresh_delta_id,'') FROM weather_pending WHERE state='pending' ORDER BY rowid LIMIT ?1",-1,&q,NULL)!=SQLITE_OK)return 0;
 if(scoped){sqlite3_bind_text(q,1,only_source,-1,SQLITE_TRANSIENT);sqlite3_bind_text(q,2,refresh?refresh_id:"",-1,SQLITE_TRANSIENT);sqlite3_bind_int(q,3,limit);}else sqlite3_bind_int(q,1,limit);
 while(sqlite3_step(q)==SQLITE_ROW){const char*acq=(const char*)sqlite3_column_text(q,0),*id=(const char*)sqlite3_column_text(q,1),*owner=(const char*)sqlite3_column_text(q,2),*body=(const char*)sqlite3_column_text(q,3),*state=(const char*)sqlite3_column_text(q,4),*last=(const char*)sqlite3_column_text(q,5);char src[512]={0},tier[32]={0},decision[160]={0};int refs,go=0;(*examined)++;
  if(!source_ref(a,id,src,sizeof(src))||!remember_source(d,acq,src))goto fail;if(scoped&&strcmp(src,only_source))goto fail;refs=lease_count(l,id);if(refs<0)goto fail;
  if(state&&!strcmp(state,"admitted")){if(refs==0)continue;if(!weather_tier(d,weather,src,tier,sizeof(tier))||!weather_decision(d,weather,src,decision,sizeof(decision)))goto fail;go=!strcmp(tier,"HOT")||!strcmp(tier,"WARM");if(refresh&&go&&!strcmp(decision,"due")&&(!last||strcmp(last,refresh_id))){if(!emit_refresh(out,refresh_id,acq,id,owner)||sqlite3_prepare_v2(d,"UPDATE weather_pending SET refresh_delta_id=?2,tier=?3,updated_at=?4 WHERE acquire_id=?1",-1,&mark,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_text(mark,1,acq,-1,SQLITE_TRANSIENT);sqlite3_bind_text(mark,2,refresh_id,-1,SQLITE_TRANSIENT);sqlite3_bind_text(mark,3,tier,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(mark,4,(sqlite3_int64)time(NULL));if(sqlite3_step(mark)!=SQLITE_DONE)goto fail;sqlite3_finalize(mark);mark=NULL;(*refreshed)++;}continue;
  }
  if(refs==0){(*stale)++;if(sqlite3_prepare_v2(d,"UPDATE weather_pending SET state='cancelled',tier='STALE_ZERO_LEASE',updated_at=?2 WHERE acquire_id=?1",-1,&mark,NULL)!=SQLITE_OK)goto fail;}else{if(!weather_tier(d,weather,src,tier,sizeof(tier)))goto fail;go=!strcmp(tier,"HOT")||!strcmp(tier,"WARM");if(go){if(!emit(out,acq,body))goto fail;if(sqlite3_prepare_v2(d,"UPDATE weather_pending SET state='admitted',tier=?2,updated_at=?3 WHERE acquire_id=?1",-1,&mark,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_text(mark,2,tier,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(mark,3,(sqlite3_int64)time(NULL));(*admitted)++;}else{if(sqlite3_prepare_v2(d,"UPDATE weather_pending SET tier=?2,updated_at=?3 WHERE acquire_id=?1",-1,&mark,NULL)!=SQLITE_OK)goto fail;sqlite3_bind_text(mark,2,tier,-1,SQLITE_TRANSIENT);sqlite3_bind_int64(mark,3,(sqlite3_int64)time(NULL));(*held)++;}}sqlite3_bind_text(mark,1,acq,-1,SQLITE_TRANSIENT);if(refs==0)sqlite3_bind_int64(mark,2,(sqlite3_int64)time(NULL));if(sqlite3_step(mark)!=SQLITE_DONE)goto fail;sqlite3_finalize(mark);mark=NULL;}
 sqlite3_finalize(q);return 1;fail:sqlite3_finalize(q);sqlite3_finalize(mark);return 0;}
int main(int argc,char**argv){const char*dbp=arg(argc,argv,"--db"),*addressp=arg(argc,argv,"--address-db"),*leasep=arg(argc,argv,"--lease-db"),*weather=arg(argc,argv,"--weather"),*acq=arg(argc,argv,"--acquire-dir"),*can=arg(argc,argv,"--cancel-dir"),*out=arg(argc,argv,"--out-dir"),*source=arg(argc,argv,"--source"),*refresh=arg(argc,argv,"--refresh-id"),*lr=arg(argc,argv,"--limit");sqlite3*d=NULL,*a=NULL,*l=NULL;int af=0,cf=0,cancelled=0,admitted=0,refreshed=0,held=0,stale=0,examined=0,limit=lr?atoi(lr):256,ok=0;enum{WG_DRAIN};static const BfCommandEntry gate_commands[]={{"drain",WG_DRAIN,0,NULL},};const BfCommandEntry*command=argc<2?NULL:bf_command_lookup(gate_commands,sizeof(gate_commands)/sizeof(gate_commands[0]),argv[1]);if(argc<2||!command||command->id!=WG_DRAIN||!dbp||!addressp||!leasep||!weather||!out||((refresh&&*refresh)&&(!source||!*source))){fputs("usage: bonfyre-material-weather-gate drain --db DB --address-db DB --lease-db DB --weather JSON --acquire-dir DIR --cancel-dir DIR --out-dir DIR [--source SOURCE --refresh-id DELTA] [--limit N]\n",stderr);return 2;}if(limit<1)limit=1;if(limit>4096)limit=4096;if(sqlite3_open(dbp,&d)!=SQLITE_OK||sqlite3_open_v2(addressp,&a,SQLITE_OPEN_READONLY,NULL)!=SQLITE_OK||sqlite3_open_v2(leasep,&l,SQLITE_OPEN_READONLY,NULL)!=SQLITE_OK||!sql(d,"PRAGMA journal_mode=WAL;CREATE TABLE IF NOT EXISTS weather_pending(acquire_id TEXT PRIMARY KEY,identity TEXT NOT NULL,owner_ref TEXT NOT NULL,handoff_json TEXT NOT NULL,source_ref TEXT,state TEXT NOT NULL CHECK(state IN ('pending','admitted','cancelled')),tier TEXT NOT NULL,refresh_delta_id TEXT NOT NULL DEFAULT '',updated_at INTEGER NOT NULL);CREATE INDEX IF NOT EXISTS weather_pending_identity ON weather_pending(identity,state);"))goto done;if(!has_column(d,"weather_pending","source_ref")&&!sql(d,"ALTER TABLE weather_pending ADD COLUMN source_ref TEXT"))goto done;if(!has_column(d,"weather_pending","refresh_delta_id")&&!sql(d,"ALTER TABLE weather_pending ADD COLUMN refresh_delta_id TEXT NOT NULL DEFAULT ''"))goto done;if(!sql(d,"CREATE INDEX IF NOT EXISTS weather_pending_source_state ON weather_pending(source_ref,state)"))goto done;if(!scan(d,l,acq,0,&af,&cancelled)||!scan(d,l,can,1,&cf,&cancelled)||!drain(d,a,l,weather,out,source,refresh,limit,&admitted,&refreshed,&held,&stale,&examined))goto done;printf("{\"acquire_files_seen\":%d,\"cancel_files_seen\":%d,\"pending_cancelled\":%d,\"admitted\":%d,\"refreshes_emitted\":%d,\"held\":%d,\"stale_zero_lease\":%d,\"pending_examined\":%d,\"source_filter\":\"%s\",\"truth\":\"lease_intent_gated_by_resource_weather\",\"cannot_infer\":[\"WARM or HOT -> authority\",\"admitted or refreshed -> successful observation\",\"COLD or FROZEN -> no semantic demand\"]}\n",af,cf,cancelled,admitted,refreshed,held,stale,examined,source?source:"");ok=1;done:if(l)sqlite3_close(l);if(a)sqlite3_close(a);if(d)sqlite3_close(d);return ok?0:1;}
